<template><section class="panel sequence-viz-field-atlas" :data-chart-id="omics==='genome'?'GB08':'TB11'" data-testid="sequence-field-atlas"><div class="section-header"><div><h3>Complete original field atlas &amp; native quantile table</h3><p class="muted">Every numeric field uses the complete primary population. Metadata columns are audited separately.</p></div><a :href="download">All field summaries CSV</a></div><div class="sequence-viz-controls"><label>Search fields<input v-model="query" class="input" @input="page=1" /></label><button class="btn subtle" :disabled="page===1" @click="page--">Previous 6 fields</button><span>{{ page }} / {{ pages }} · {{ total }} fields</span><button class="btn subtle" :disabled="page>=pages" @click="page++">Next 6 fields</button></div><p v-if="error">{{ error }}</p><ModuleState v-else-if="loading" state="loading" title="Loading field profiles"/><div v-else class="sequence-viz-field-grid"><section v-for="p in profiles" :key="p.field"><h4>{{ p.field }} · {{ p.unit }}</h4><p class="sequence-viz-caption"><a :href="exactDownload(p.field,'csv')">Exact full-field ECDF CSV</a> · <a :href="exactDownload(p.field,'tsv')">TSV</a></p><EChart :option="fieldOption(p)" :height="510" :auto-loading="false" :show-data-exports="false" :export-name="speciesId+'_'+omics+'_'+scope+'_'+p.field+'_'+manifest.artifact_version"/><p class="sequence-viz-caption">n={{ p.n_valid }} · missing={{ p.n_missing }} · zero={{ p.n_zero }} · {{ p.histogram.kind }}</p><p class="sequence-viz-caption">Min / P05 / P25 / Median / P75 / P95 / Max: {{ p.quantiles?.map(v=>fmt(v)).join(' / ')||'unavailable' }}</p></section></div><div class="table-wrap" :data-chart-id="omics==='genome'?'GB09':'TB12'"><table><thead><tr><th>Field</th><th>Unit</th><th>Valid</th><th>Missing</th><th>Zero</th><th>Invalid</th><th>Mean</th><th>Min / P05 / P25 / Median / P75 / P95 / Max</th></tr></thead><tbody><tr v-for="p in profiles" :key="p.field"><td>{{ p.field }}</td><td>{{ p.unit }}</td><td>{{ p.n_valid }}</td><td>{{ p.n_missing }}</td><td>{{ p.n_zero }}</td><td>{{ p.n_invalid }}</td><td>{{ fmt(p.mean) }}</td><td>{{ p.quantiles?.map(v=>fmt(v)).join(' / ') }}</td></tr></tbody></table></div><details><summary>All original metadata and field provenance ({{ manifest.catalog?.filter(c=>c.primary).length }} primary columns)</summary><div class="table-wrap"><table><thead><tr><th>Field</th><th>Role</th><th>Source</th><th>Primary</th><th>Valid metadata</th><th>Unique</th></tr></thead><tbody><tr v-for="c in manifest.catalog" :key="c.key"><td>{{ c.key }}</td><td>{{ c.role }}</td><td>{{ c.source_file_scope }}</td><td>{{ c.primary }}</td><td>{{ manifest.metadata_coverage?.find(m=>m.field===c.key)?.n_valid??'' }}</td><td>{{ manifest.metadata_coverage?.find(m=>m.field===c.key)?.n_unique??'' }}</td></tr></tbody></table></div></details></section></template>
<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import EChart from '../EChart.vue';import ModuleState from '../ModuleState.vue';import {sequenceGet,sequenceExport} from '../../api/sequenceVisuals';import {sequenceOption} from '../../utils/sequenceCharts';import {number as fmt} from '../../utils/sequenceFormat'
const props=defineProps({speciesId:String,omics:String,scope:String,manifest:Object});const page=ref(1),query=ref(''),profiles=ref([]),total=ref(0),error=ref(''),loading=ref(false);let seq=0,controller
const pages=computed(()=>Math.max(1,Math.ceil(total.value/6))),download=computed(()=>sequenceExport(props.speciesId,props.omics,{scope:props.scope,kind:'all_fields',artifact_version:props.manifest.artifact_version,source_hash:props.manifest.source_hash}))
function exactDownload(field,file_format){return sequenceExport(props.speciesId,props.omics,{scope:props.scope,artifact_version:props.manifest.artifact_version,source_hash:props.manifest.source_hash,kind:'exact_ecdf',field,file_format,chart_id:props.omics==='genome'?'GB08':'TB11'})}
function fieldOption(p){
 const o=sequenceOption({data:{kind:'distribution_ecdf',profile:{...p,axis_label:'Original value'}},__narrow:true});if(o.grid?.[1])o.grid[1].height='22%';o.graphic=[{type:'text',left:12,bottom:3,silent:true,style:{text:`${props.speciesId} · ${props.omics} · ${props.scope} · n_source=${props.manifest.n_source} · n_valid=${p.n_valid}\n${p.field} · ${props.manifest.method_version} · ${props.manifest.artifact_version}`,fontSize:9,lineHeight:12,fill:'#526575'}}];return o
}
async function load(){const current=++seq;controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const r=await sequenceGet(props.speciesId,props.omics,'fields/',{scope:props.scope,artifact_version:props.manifest.artifact_version,source_hash:props.manifest.source_hash,page:page.value,page_size:6,q:query.value},{signal:controller.signal});if(seq!==current)return;profiles.value=r.profiles;total.value=r.total}catch(e){if(seq===current&&!controller.signal.aborted)error.value=e.message}finally{if(seq===current)loading.value=false}}
watch(()=>[props.speciesId,props.omics,props.scope,props.manifest.artifact_version],()=>{page.value=1;query.value='';load()},{immediate:true});watch([page,query],load);onBeforeUnmount(()=>{seq++;controller?.abort()})
</script>
